func Blake_update_32(ctx *Crypto_blake2b_ctx, input uint32) {
	var v2 [4]uint8
	Store32_le(v2[:], input)
	Crypto_blake2b_update(ctx, v2[:], uint64(4))
	clear(v2[:])
}

