func Extended_hash(digest []byte, digest_size uint32, input []byte, input_size uint32) {
	var v28 uint32
	var v30 uint32
	var v32 uint32
	var v5 Crypto_blake2b_ctx
	Crypto_blake2b_init(&v5, uint64(min(digest_size, uint32(64))))
	Blake_update_32(&v5, digest_size)
	Crypto_blake2b_update(&v5, input, uint64(input_size))
	Crypto_blake2b_final(&v5, digest)
	if digest_size > 64 {
		v27 := uint32((uint64(digest_size)+31)>>5) - 2
		v28 = 1
		v30 = 0
		v32 = 32
		for v28 < v27 {
			Crypto_blake2b(digest[v32:], uint64(64), digest[v30:], uint64(64))
			v28++
			v30 += 32
			v32 += 32
		}
		Crypto_blake2b(digest[v32:], uint64(digest_size-(uint32(32)*v27)), digest[v30:], uint64(64))
	}
}
